function tankArea(a){
  if(a.shape==='rectangle')return a.l*a.w;
  if(a.shape==='cylinder')return Math.PI*(a.l/2)**2;
  if(a.shape==='ellipse')return Math.PI*a.l*a.w/4;
  if(a.shape==='hexagon')return Math.sqrt(3)/2*a.l**2;
  if(a.shape==='corner')return Math.PI*a.l**2/4;
  // Bow-front: a rectangle plus the circular segment that bulges out at the front.
  const bulge=a.w2-a.w;
  ensure(bulge>=0,'A bow-front is deepest in the middle. The width at the center should be larger than the width at the ends.');
  ensure(bulge<=a.l/2,'That bow is deeper than a half-circle. Check the two width measurements.');
  if(bulge===0)return a.l*a.w;
  const r=(a.l*a.l/4+bulge*bulge)/(2*bulge),angle=4*Math.atan2(2*bulge,a.l);
  // theta - sin(theta) loses the curved area for an almost-flat bow.
  const segment=angle<.01?angle**3/6*(1-angle**2/20+angle**4/840):angle-Math.sin(angle);
  return a.l*a.w+r*r*segment/2;
}
